export const IMZA_SURESI = PARCALAR.at(-1)[0];

export function imzaSvg({ canli = false, altin = false, bas = 0, hiz = 1 } = {}) {
  sayac += 1;
  const altinId = `imza-altin-${sayac}`;
  const kutu = `${-PAY} ${-PAY} ${GENISLIK + PAY * 2} ${YUKSEKLIK + PAY * 2}`;
  const boya = altin ? `url(#${altinId})` : 'currentColor';
  const gecis = altin
    ? `<linearGradient id="${altinId}" gradientUnits="userSpaceOnUse" x1="0" y1="0" x2="${GENISLIK}" y2="${YUKSEKLIK}"><stop offset="0" stop-color="#fdeeb5"/><stop offset=".55" stop-color="#ecc659"/><stop offset="1" stop-color="#d09c2e"/></linearGradient>`
    : '';
  if (!canli) return `<svg viewBox="${kutu}"><defs>${gecis}</defs><path d="${MUREKKEP}" fill="${boya}"/></svg>`;
  const adimlar = PARCALAR.map(([an, yol]) => `<path class="adim" d="${yol}" style="--an:${(bas + an * hiz).toFixed(3)}s"/>`).join('');
  // Yazım bitince parçaların ek yerleri görünmesin diye tek parça imza üste gelir.
  const son = `<path class="adim" d="${MUREKKEP}" style="--an:${(bas + IMZA_SURESI * hiz + 0.05).toFixed(3)}s"/>`;
  return `<svg viewBox="${kutu}" fill="${boya}"><defs>${gecis}</defs>${adimlar}${son}</svg>`;
}
